use std :: fs ; use std :: path :: Path ; use clap :: Parser ; use serde_json ; use num_bigint :: BigUint ; use cargo_vendormod :: group_atlas :: { GroupAtlas , GroupFamily , ClassicalLieType , TwistedLieType , SporadicGroup , n } ; use cargo_vendormod :: visualization :: { AtlasRenderer , AtlasConfig } ; # [doc = " Format compositions for README"] fn format_compositions (atlas : & GroupAtlas) -> String { if atlas . compositions . is_empty () { "No compositions generated" . to_string () } else { atlas . compositions . iter () . take (5) . map (| c | format ! ("- {}" , c . name)) . collect :: < Vec < _ > > () . join ("\n") } }